-- ======================= STORAGE POLICIES =======================
-- These govern who may read and write the three buckets. They live
-- in the storage schema and were absent from the first snapshot.

CREATE POLICY call_audio_org_delete ON storage.objects AS PERMISSIVE FOR DELETE TO authenticated
  USING (((bucket_id = 'call-audio'::text) AND ((storage.foldername(name))[1] = (current_user_org_id())::text)));

CREATE POLICY call_audio_org_insert ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK (((bucket_id = 'call-audio'::text) AND ((storage.foldername(name))[1] = (current_user_org_id())::text)));

CREATE POLICY call_audio_org_read ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated
  USING (((bucket_id = 'call-audio'::text) AND ((storage.foldername(name))[1] = (current_user_org_id())::text)));

CREATE POLICY cvs_org_delete ON storage.objects AS PERMISSIVE FOR DELETE TO authenticated
  USING (((bucket_id = 'cvs'::text) AND ((storage.foldername(name))[1] = (( SELECT current_user_org_id() AS current_user_org_id))::text) AND ( SELECT can_write_candidates() AS can_write_candidates)));

CREATE POLICY cvs_org_insert ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK (((bucket_id = 'cvs'::text) AND ((storage.foldername(name))[1] = (( SELECT current_user_org_id() AS current_user_org_id))::text) AND ( SELECT can_write_candidates() AS can_write_candidates)));

CREATE POLICY cvs_org_read ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated
  USING (((bucket_id = 'cvs'::text) AND ((storage.foldername(name))[1] = (( SELECT current_user_org_id() AS current_user_org_id))::text) AND ( SELECT can_read_org() AS can_read_org)));

CREATE POLICY cvs_org_update ON storage.objects AS PERMISSIVE FOR UPDATE TO authenticated
  USING (((bucket_id = 'cvs'::text) AND ((storage.foldername(name))[1] = (( SELECT current_user_org_id() AS current_user_org_id))::text) AND ( SELECT can_write_candidates() AS can_write_candidates)))
  WITH CHECK (((bucket_id = 'cvs'::text) AND ((storage.foldername(name))[1] = (( SELECT current_user_org_id() AS current_user_org_id))::text) AND ( SELECT can_write_candidates() AS can_write_candidates)));

CREATE POLICY invoice_assets_org_delete ON storage.objects AS PERMISSIVE FOR DELETE TO authenticated
  USING (((bucket_id = 'invoice-assets'::text) AND ((storage.foldername(name))[1] = (current_user_org_id())::text)));

CREATE POLICY invoice_assets_org_insert ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK (((bucket_id = 'invoice-assets'::text) AND ((storage.foldername(name))[1] = (current_user_org_id())::text)));

CREATE POLICY invoice_assets_org_read ON storage.objects AS PERMISSIVE FOR SELECT TO authenticated
  USING (((bucket_id = 'invoice-assets'::text) AND ((storage.foldername(name))[1] = (current_user_org_id())::text)));


-- ======================= COMMENTS =======================
-- Not decoration. Several carry the reasoning for a deliberate
-- advisor exemption (migration 160) and would be lost in a
-- rebuild that skipped them.

COMMENT ON INDEX public.candidate_erasure_requests_open_key_idx IS '§209 D4 — one open erasure request per IDENTITY. It used to be one per PERSON, which meant two people who had each asked to be forgotten could not be merged at all: the merge repoints every request to the survivor, and the second repoint was a duplicate key that aborted the merge whole. Several open requests may now stand against one person; candidate_erasure_requests.suppression_id is what keeps each one answerable.';

COMMENT ON COLUMN public.candidate_erasure_requests.network_profile_id IS 'S207 D1 — the PERSON this request is about, resolved when it was filed (their profile, else the person an alias says the key belongs to). Repointed by merge_network_profiles so it follows a merge (D2); ON DELETE SET NULL so the request outlives the person it erased.';

COMMENT ON COLUMN public.candidate_erasure_requests.covered_candidate_ids IS 'S207 D1 — the candidate rows this ask covers. Written when the request is filed, and ADDED TO (never recomputed, never narrowed) by a human merge that brings more of this person''s records together — 153. It is the arm that still answers after an identity edit has moved a row to a different person AND changed the key it computes. Closed requests are never widened: their array is a receipt of what was erased.';

COMMENT ON COLUMN public.candidate_erasure_requests.decline_kind IS 'S207 D5 — which decline this was. cannot_erase: the data is retained under the retention verdict and the person stays suppressed. not_subject: the filer was not the person (a forwarded portal link), so the suppression the request itself set is lifted with it.';

COMMENT ON COLUMN public.candidate_erasure_requests.suppression_id IS '§209 D1 — the network_suppressions row 098''s immediate suppression wrote when this request was filed, or NULL when the request suppressed nobody (no resolvable person) or predates this slice ambiguously. A not_subject decline lifts THIS row and no other. ON DELETE SET NULL because the ledger row outranks the pointer: a request that can no longer name its row must lift nothing rather than guess, which is the whole defect this column closes.';

COMMENT ON COLUMN public.candidate_scores.rank_changed_at IS 'Set whenever previous_rank != rank_position after a scoring run. Used by the ranking page to show "moved 2h ago".';

COMMENT ON COLUMN public.candidate_scores.rank_change_reason IS 'Structured payload describing what triggered the move:
  { trigger: "feedback" | "recalibration" | "new_candidate" | "weights_edit" | "scoring_run",
    feedback_id?: uuid,
    summary?: string,
    weight_deltas?: { dimension: string, before: int, after: int }[],
    dimension_score_deltas?: { dimension: string, before: number, after: number }[] }
Attached during computeAndStoreScores() and downstream callers (recalibrate, manual weight edits).';

COMMENT ON COLUMN public.candidate_scores.custom_scores IS '§196 — 0-10 scores for this project''s APPROVED custom dimensions, keyed by dimension slug. {} means none assessed. Written only by the scoring engine, and only for keys approvedCustomDimensions() returns; an absent key is excluded from the weighted average rather than scored zero.';

COMMENT ON COLUMN public.candidates.created_by IS 'Who uploaded/added this candidate. NULL = unowned (pre-140 rows, or the owner''s account was deleted) and unowned is in EVERY trawl. Scopes the reuse agent''s search only — never visibility (§200 D1).';

COMMENT ON COLUMN public.candidates.cv_sha256 IS 'SHA-256 (lowercase hex) of the stored CV bytes. Document identity, NOT person identity — see candidate_identity_key for the latter. NULL for every row created before migration 141, and for rows with no file. Written by the upload action from the bytes the SERVER received; a hash computed in the browser is never trusted.';

COMMENT ON COLUMN public.candidates.identity_review_of IS 'The row this candidate matched on name|company only. ON DELETE SET NULL: if the other row goes, the pointer goes and identity_review_label still reads.';

COMMENT ON COLUMN public.candidates.identity_review_label IS 'The matched row''s name as it was when the flag was raised. Snapshotted for the same reason member_org_changed snapshots org names — the sentence has to stay readable after the row it points at is gone.';

COMMENT ON COLUMN public.candidates.identity_review_at IS 'When the flag was raised. This, not identity_review_of, is what marks a row as flagged — the pointer can null out, the fact that a human was asked cannot.';

COMMENT ON COLUMN public.candidates.cv_search IS '§205 — the five fields the Network search box promises, lowercased into one inline column so the trigram index is reachable and the row''s toasted CV is never detoasted to answer a search. Derived, never written to.';

COMMENT ON COLUMN public.executive_role_templates.created_by IS 'The admin who authored an org template. NULL on the global seeds.';

COMMENT ON COLUMN public.feedback.answers_json IS 'Structured source of a composed client-interview answer (127): the question-id -> answer map the client typed, kept so the author can EDIT under D3(c) rather than retype. NULL on every other feedback_type and on every row written before 127.';

COMMENT ON TABLE public.network_profile_aliases IS 'Identity keys that resolve to a person they do not literally key, because a recruiter merged two profiles. Consulted by resolve_network_profile BEFORE find-or-create, which is what makes a merge survive an ordinary edit AND lets a future CV under the old key rejoin the right person. ON DELETE CASCADE on profile_id: if the person is deleted the alias is meaningless.';

COMMENT ON TABLE public.network_suppressions IS 'S208 — every reason a person is not to be contacted, one row each, never overwritten and never deleted. network_profiles.dnc and its three companions are DERIVED from the earliest unlifted row here (refresh_network_suppression). carried_from records lineage so a lift can travel exactly as far as the suppression did, and no further.';

COMMENT ON COLUMN public.network_suppressions.moved_from_profile IS '§209 D2 — the person this reason was filed against before a merge moved it here, or NULL if it has always been this person''s. A MOVE IS NOT A COPY: `carried_from` is what a lift follows, and this column never widens a lift by one person. No FK — the profile it names is deleted by the same merge that stamps it.';

COMMENT ON COLUMN public.projects.client_psychology IS 'Hiring-manager preference model derived from feedback patterns. See src/lib/ai/client-psychology-agent.ts for the shape.';

COMMENT ON COLUMN public.projects.health_suggestions IS 'AI-generated health remediation suggestions. See src/lib/ai/search-health-agent.ts for the shape.';

COMMENT ON COLUMN public.projects.intake_error IS 'Terminal intake-analysis failure sentence, rendered verbatim with a retry CTA. NULL while analyzing and after success (the success UPDATE clears it). Written only by the human half: the seam''s failure bookkeeping and the poller''s guarded timeout marker. Sanitised via safeFailureMessage — provider payloads never land here.';

COMMENT ON COLUMN public.users.manager_id IS 'Whose desk this member reports to. Read ONE level deep by the reuse agent: a manager trawls their own CVs plus those of everyone whose manager_id is them. Not a permission.';

COMMENT ON VIEW public.network_people_folded IS '§205 — the Network page''s fold: one row per network_profile_id, read directly by the page (13 ms at 2,135 people, against 785 ms for the same SQL inside a row-set function). `search_text` is the person''s records'' cv_search concatenated, so a search filters people in one predicate. security_invoker: the org scope stays RLS''s job.';

COMMENT ON FUNCTION public.candidate_erasure_open(p_candidate_id uuid) IS 'S207 D1 — does an unresolved erasure request stand against this candidate row? Four arms, ORed: the person, the person under a pre-merge alias, the key the row computes now, and the rows the request froze when it was filed. SECURITY INVOKER: RLS scopes every table, and both callers are the reader''s own session.';

COMMENT ON FUNCTION public.candidates_link_network_profile() IS '§196/139 — mints no network person while cv_processing is true and the only identity signal is a name, so a CV upload no longer leaves a person named after the file. §193 declared-identity hold runs first and is unaffected. §207 slice 1 — when an identity edit repoints the row to a DIFFERENT person, carry_network_suppression carries do-not-contact across: adding somebody''s email used to un-suppress them.';

COMMENT ON FUNCTION public.carry_network_suppression(p_from uuid, p_to uuid) IS '§207 slice 1 — carries do-not-contact from one person to another when a candidate row is repointed between them by an identity edit. Contagious and never lowered (§203 D2''s rule, same question): the earlier suppression wins, the ORIGINAL reason/when/who travel, the source keeps theirs. Org-scoped. Writes through guard_network_dnc''s own door.';

COMMENT ON FUNCTION public.count_network_people() IS '§204 — counts DISTINCT network_profile_id, so a merge (§203) moves the badge. Rows with no person yet (§196/139, cv_processing with only a name) are excluded, matching the Network page''s fold. RLS-scoped: not security definer.';

COMMENT ON FUNCTION public.merge_candidates(p_keep uuid, p_discard uuid) IS 'Merge two candidate records of one person within ONE mandate, in a single transaction. Gate 2026-09-25: the survivor wins every one-per-candidate collision (D1) and the receipt names each drop; all notes, feedback, outreach and trail move (D2); a placement on the discarded record REFUSES the merge (D3); blank fields on the survivor are filled from the discarded record, never overwritten (D4). Reparents feedback BEFORE deleting because feedback_candidate_id_fkey is NO ACTION and blocks. Returns a receipt; the caller deletes the discarded CV object, which SQL cannot reach.';

COMMENT ON FUNCTION public.merge_network_profiles(p_keep uuid, p_discard uuid) IS 'Merge two network profiles of one person within one organisation, in a single transaction. Gate 2026-09-25: the loser''s identity key becomes an ALIAS of the survivor so the merge survives an ordinary edit and a future CV under the old key rejoins (D1); suppression is contagious and never lowered, carrying the ORIGINAL reason/when/who, through guard_network_dnc''s own door (D2); the warmer state and the most recent contact survive, earliest follow-up kept (D3); org-scoped, agents refused (D4).';

COMMENT ON FUNCTION public.network_domains() IS '§205 — distinct domains for the Network page''s filter, so the dropdown offers every value in the pool rather than the ones that happen to be on page one.';

COMMENT ON FUNCTION public.network_people_matches(p_row_archetype text, p_row_domain text, p_row_tier text, p_row_years numeric, p_row_stages text[], p_archetype text, p_tier text, p_domain text, p_stage text, p_years text) IS '§205 — the Network page''s filter rule, written once and inlined into both the paged reader and the rollup. Archetype, domain and years read the canonical record; stage matches ANY appearance; tier is the person''s best. 160: search_path is left MUTABLE ON PURPOSE. A SET clause would make this non-inlinable and cost the predicate pushdown 148 tuned for, while buying nothing — the body names only pg_catalog built-ins, which the path cannot preempt. The advisor''s function_search_path_mutable finding on this function is expected. If this body ever references one of our own objects, pin the path in that migration.';

COMMENT ON FUNCTION public.network_people_rollup(p_q text, p_archetype text, p_tier text, p_domain text, p_stage text, p_years text) IS '§205 — the Network page''s figures, over the whole FILTERED pool rather than the page. plpgsql with EXECUTE ... USING so each call gets a plan for the filters it actually has: as a plain SQL function the same aggregate took 835 ms at 2,135 people, and 12 ms this way. Filters go through network_people_matches, the one rule the page''s own clauses mirror.';

COMMENT ON FUNCTION public.network_suppressions_stamp_move() IS '§209 D2 — stamps a suppression with the person it was moved off, the first time it moves. `moved_from_profile IS NULL` guards it so a merge of a merge keeps naming the person the reason ORIGINALLY belonged to rather than the most recent waypoint. `carried_from` is never touched: a move is not a copy, and a lift still travels only along copies.';

COMMENT ON FUNCTION public.portal_get_mandate(p_project_id uuid) IS '§196/138 — client portal mandate read. calibration_model is a NAMED PROJECTION, not the stored row: only dimension_weights and APPROVED custom dimensions cross, and custom dimensions cross without their rationale. Adding a key here puts it in a client''s hands.';

COMMENT ON FUNCTION public.record_activity_event(p_event_type text, p_project_id uuid, p_candidate_id uuid, p_client_id uuid, p_detail jsonb) IS 'The application''s door onto the activity trail. 27 app-recordable event types (141 added candidate_duplicate_discarded), each gated on the capability that authorises the act it claims. SECURITY DEFINER; stamps actor_id from auth.uid() so a caller cannot attribute an act to somebody else.';

COMMENT ON FUNCTION public.record_email_delivery_event(p_provider_message_id text, p_status text, p_address text, p_detail text) IS '099/126 — records a Resend delivery event and suppresses genuine bounces. §211: service_role ONLY. It is SECURITY DEFINER and bypasses the _admin_insert-only RLS on email_suppressions, so an anon/authenticated caller could write a suppression it was forbidden to write (confused deputy, vuln finding 1). Authenticity now lives where it belongs — the webhook route verifies the Svix signature, then calls this as service_role.';

COMMENT ON FUNCTION public.relationship_warmth(p_state text) IS '§205 — warmth as an ordinal, so a merge can compare two relationship states. 160: search_path pinned empty; the body names nothing outside pg_catalog. Callable by authenticated and service_role only (158).';

COMMENT ON FUNCTION public.run_guarantee_maintenance() IS '062 — earns guarantee_passed instalments past their date. §211: service_role ONLY. It is an unguarded SECURITY DEFINER write; the CRON_SECRET at /api/cron/maintenance is the authenticity boundary, and the route now calls this as service_role rather than leaving the RPC open to anon.';

COMMENT ON FUNCTION public.update_cv_structured_field(p_candidate_id uuid, p_project_id uuid, p_key text, p_value jsonb) IS 'Atomically set or delete a single top-level key on candidates.cv_structured. NULL p_value deletes the key. RLS-bound (SECURITY INVOKER).';

COMMENT ON FUNCTION public.verify_hm_token(p_token uuid) IS 'Verify a hiring-manager share token and bump its last_used_at. Returns (project_id, organization_id, label) when valid, empty result when revoked/expired/unknown. SECURITY DEFINER.';

-- end of schema reference
